import{_ as d,o,c,a1 as t}from"./chunks/framework.BKrM4vFX.js";const h=JSON.parse('{"title":"first-ofd-mock — облачная касса OKassa (Первый ОФД)","description":"first-ofd-mock — облачная касса OKassa (Первый ОФД). © 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0 SPDX-License-Identifier: Apache-2.0 Третий внешний касса-адаптер Stage 2 (issue #92, «добор kassa/OFD»), восьмой сервис стенда. Реализован по официальной д","frontmatter":{"sourcePath":"services/first-ofd-mock/README.md"},"headers":[{"level":1,"title":"first-ofd-mock — облачная касса OKassa (Первый ОФД)","slug":"first-ofd-mock-облачная-касса-okassa-Первый-ОФД","link":"#first-ofd-mock-облачная-касса-okassa-Первый-ОФД","children":[{"level":2,"title":"Быстрый старт","slug":"Быстрый-старт","link":"#Быстрый-старт","children":[]},{"level":2,"title":"Поддерживаемый поток OKassa","slug":"Поддерживаемый-поток-okassa","link":"#Поддерживаемый-поток-okassa","children":[]},{"level":2,"title":"Авторизация и токен","slug":"Авторизация-и-токен","link":"#Авторизация-и-токен","children":[]},{"level":2,"title":"Очередь, статусы и деньги","slug":"Очередь-статусы-и-деньги","link":"#Очередь-статусы-и-деньги","children":[]},{"level":2,"title":"Callback","slug":"callback","link":"#callback","children":[]},{"level":2,"title":"Идемпотентность и externalId","slug":"Идемпотентность-и-externalid","link":"#Идемпотентность-и-externalid","children":[]},{"level":2,"title":"Сценарии, часы и диагностика","slug":"Сценарии-часы-и-диагностика","link":"#Сценарии-часы-и-диагностика","children":[]},{"level":2,"title":"Переменные окружения","slug":"Переменные-окружения","link":"#Переменные-окружения","children":[]},{"level":2,"title":"Протокольные файлы и тесты","slug":"Протокольные-файлы-и-тесты","link":"#Протокольные-файлы-и-тесты","children":[]},{"level":2,"title":"Байтовые квоты состояния (PD-02)","slug":"Байтовые-квоты-состояния-pd-02","link":"#Байтовые-квоты-состояния-pd-02","children":[]}]}],"relativePath":"services/first-ofd-mock/README.md","filePath":"services/first-ofd-mock/README.md"}'),a={name:"services/first-ofd-mock/README.md"};function s(r,e,i,l,n,_){return o(),c("div",null,[...e[0]||(e[0]=[t('<p>© 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0 SPDX-License-Identifier: Apache-2.0</p><h1 id="first-ofd-mock-облачная-касса-okassa-Первый-ОФД" tabindex="-1">first-ofd-mock — облачная касса OKassa (Первый ОФД) <a class="header-anchor" href="#first-ofd-mock-облачная-касса-okassa-Первый-ОФД" aria-label="Permalink to &quot;first-ofd-mock — облачная касса OKassa (Первый ОФД)&quot;">​</a></h1><nav class="doc-static-toc" aria-label="Оглавление"><p class="doc-static-toc__title">Оглавление</p><ul><li class="doc-static-toc__item doc-static-toc__item--1"><a class="doc-static-toc__link" href="#first-ofd-mock-облачная-касса-okassa-Первый-ОФД">first-ofd-mock — облачная касса OKassa (Первый ОФД)</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Быстрый-старт">Быстрый старт</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Поддерживаемый-поток-okassa">Поддерживаемый поток OKassa</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Авторизация-и-токен">Авторизация и токен</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Очередь-статусы-и-деньги">Очередь, статусы и деньги</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#callback">Callback</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Идемпотентность-и-externalid">Идемпотентность и externalId</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Сценарии-часы-и-диагностика">Сценарии, часы и диагностика</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Переменные-окружения">Переменные окружения</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Протокольные-файлы-и-тесты">Протокольные файлы и тесты</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Байтовые-квоты-состояния-pd-02">Байтовые квоты состояния (PD-02)</a></li></ul></nav><p>Третий внешний касса-адаптер Stage 2 (issue #92, «добор kassa/OFD»), восьмой сервис стенда. Реализован по официальной документации OKassa API и тестового стенда Первого ОФД (срез 2026-10-11): тестовый контур <code>external-api-farm.1-ofd-test.ru</code>, <code>getToken</code> → <code>Authorization: Bearer</code>, <strong>асинхронная очередь заявок на чек</strong><code>POST /api/external/queue/v1/transaction/{type}</code> → <code>requestId</code>, статусы <code>IN_PROGRESS</code>/<code>COMPLETED</code>/<code>ERROR</code>.</p><p>Это <strong>не Ferma (<code>kassa-mock</code>) и не АТОЛ</strong>: другой транспорт, другая модель (очередь заявок, а не синхронный вызов), операции записаны как <code>INCOME</code>, <code>INCOME_RETURN</code>, <code>EXPENCE</code>, <code>EXPENCE_RETURN</code>. Тег ATOL Online V5 из тестового swagger Первого ОФД (<code>/api/external/possystem/v5/…</code>) — отдельный API и вне области адаптера.</p><h2 id="Быстрый-старт" tabindex="-1">Быстрый старт <a class="header-anchor" href="#Быстрый-старт" aria-label="Permalink to &quot;Быстрый старт&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:first-ofd</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # http://localhost:3107</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># или общий локальный стенд:</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> first-ofd-mock</span></span></code></pre></div><p>Node ≥ 18, zero npm dependencies. Синтетические дефолты — <code>firstofdmocktest</code> / <code>11111111-2222-4333-8444-555555555555</code>; это <strong>не</strong> реквизиты Первого ОФД: публичных тестовых login/API-key UUID у провайдера нет, они выдаются в тестовом ЛК. Фактические env-значения при запуске скрыты в логах (<code>&lt;задан через env, скрыт&gt;</code>). Реальные тестовые креды не помещайте в код, тесты, fixtures или общий compose-файл.</p><h2 id="Поддерживаемый-поток-okassa" tabindex="-1">Поддерживаемый поток OKassa <a class="header-anchor" href="#Поддерживаемый-поток-okassa" aria-label="Permalink to &quot;Поддерживаемый поток OKassa&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Маршрут</th><th>Назначение</th></tr></thead><tbody><tr><td><code>POST /getToken</code></td><td>авторизация: <code>Content-Type: application/json; charset=utf-8</code>, тело <code>{login, pass}</code> → <code>{token}</code>; <code>pass</code> — API-ключ UUID, bearer-токеном не является</td></tr><tr><td><code>POST /api/external/queue/v1/transaction/{type}</code></td><td>поставить заявку в очередь → <code>requestId</code>; <code>type</code> ∈ <code>receipt</code>, <code>receiptCorrection</code>, <code>openShift</code>, <code>closeShift</code>, <code>currentStateReport</code></td></tr><tr><td><code>GET /api/external/queue/v1/transaction/{requestId}</code></td><td>полная заявка (тело как принято) + <code>result</code></td></tr><tr><td><code>GET /api/external/queue/v1/status/{requestId}</code></td><td>текущий статус и результат (метод сверки после callback)</td></tr><tr><td><code>GET /api/external/queue/v1/statuses?externalId=&amp;groupId=</code></td><td>заявки по внешнему ID и группе; <code>externalId</code> и <code>groupId</code> обязательны, <code>status</code> — необязательный фильтр</td></tr><tr><td><code>GET /api/external/receipts?from=&amp;to=</code></td><td>фискальные документы за период (фильтры <code>transactionType</code>, <code>groupId</code>, <code>kkmRegId</code>, <code>page</code>, <code>pageSize</code>)</td></tr><tr><td><code>GET /health</code>, <code>GET /openapi.json</code></td><td>healthcheck и OpenAPI 3.1</td></tr><tr><td><code>GET /admin</code>, <code>GET /admin/journal</code>, <code>POST /admin/action</code></td><td>консоль заявок/групп/callback и журнала; действия защищены same-origin + CSRF</td></tr><tr><td><code>/mock/time</code>, <code>/mock/scenarios</code>, <code>/mock/state</code>, <code>/mock/reset</code></td><td>виртуальные часы, сценарии/хаос и состояние песочницы</td></tr><tr><td><code>/sandboxes*</code>, <code>/mock/sandboxes</code></td><td>RFC-001 sandbox/control-plane API</td></tr></tbody></table><p>Схема тела <strong>строго по типу заявки</strong>: <code>receipt</code> → <code>ReceiptRequest</code>, <code>receiptCorrection</code> → <code>ReceiptCorrectionRequest</code> (+ обязательный <code>document.correctionCause</code>), <code>openShift</code>/<code>closeShift</code>/<code>currentStateReport</code> → <code>StateCommandRequest</code>. Receipt-тело (<code>document</code> с <code>operationType</code>/<code>items</code>/ <code>totalSum</code>) в командах смены отклоняется — «универсальный» объект из схем разных провайдеров не собирается. Состав обязательных полей <code>StateCommandRequest</code> публично не раскрыт <code>[VERIFY]</code>: мок требует документированный <code>requestMetadata.userGroup</code>.</p><h2 id="Авторизация-и-токен" tabindex="-1">Авторизация и токен <a class="header-anchor" href="#Авторизация-и-токен" aria-label="Permalink to &quot;Авторизация и токен&quot;">​</a></h2><p><code>POST /getToken</code> принимает JSON с <code>login</code> и <code>pass</code> (API-ключ UUID из ЛК «Облачные кассы → Интеграции → Ключи к Кассовому API»). Успех — <code>{token}</code> + заголовки <code>X-Mock-Token-TTL-Secs</code>/<code>X-Mock-Token-Expires-At</code>; ошибки — <code>invalid_credentials</code> (401) или <code>invalid_request</code> (400). Дальше запросы несут <code>Authorization: Bearer &lt;token&gt;</code>.</p><p>Токен живёт <strong>86400</strong> секунд (24 часа) на <strong>виртуальных часах</strong>: <code>POST /mock/time {&quot;advance&quot;:&quot;+25h&quot;}</code> делает прежний токен невалидным, новый <code>getToken</code> — снова рабочим. Повторная выдача по умолчанию не аннулирует прежний токен (срез об этом молчит — <code>[VERIFY]</code>); режим <code>MOCK_FIRST_OFD_TOKEN_SINGLE=1</code> включает аннулирование, чтобы проверить и такое поведение.</p><p><strong>Квирк примера PDF.</strong> Под заголовком успешного ответа <code>getToken</code> в PDF приведён объект <code>error</code> с кодом <code>0</code> и текстом «Неверный логин и пароль» (расхождение №4 среза): по HTTP 200 нельзя однозначно судить об успехе. Мок не угадывает семантику — дефолтный успех отдаёт только <code>{token}</code>, а документированный квирк воспроизводится сценарием <code>getToken-error-quirk</code>.</p><h2 id="Очередь-статусы-и-деньги" tabindex="-1">Очередь, статусы и деньги <a class="header-anchor" href="#Очередь-статусы-и-деньги" aria-label="Permalink to &quot;Очередь, статусы и деньги&quot;">​</a></h2><p><code>POST transaction/{type}</code> возвращает <code>requestId</code> — <strong>не финальный фискальный результат</strong>: заявка сначала <code>IN_PROGRESS</code>, затем <code>COMPLETED</code> или <code>ERROR</code> (в моке обработка занимает <code>MOCK_FIRST_OFD_PROCESS_MS</code>, по умолчанию 2000 мс виртуальных часов). Объект результата несёт <code>requestId</code>, <code>transactionType</code>, <code>errorCode</code>, <code>errorType</code>, <code>details</code>, <code>payload</code>; <code>pending</code>-поля равны <code>null</code>.</p><p>Ошибки двух слоёв сохраняются раздельно: <code>errorType=API</code> — слой API очереди, <code>errorType=KKT</code> — слой ККТ/фискального накопителя. Таблица значений публично не зафиксирована, поэтому каталоги <code>KKT_ERROR_CODES</code>/<code>API_ERROR_CODES</code> — явный <code>[FORK]</code> мока.</p><p>Денежные значения (<code>price</code>, <code>totalSum</code>, <code>vatSums</code>, <code>ecashSums</code>) — <strong>десятичные рубли</strong> (<code>150.00</code>), не копейки; внутри стенд считает в целых копейках. Операции <code>INCOME</code>/<code>INCOME_RETURN</code>/<code>EXPENCE</code>/<code>EXPENCE_RETURN</code> и ставки НДС включая <code>VAT_22</code>/<code>VAT_22122</code> — как в схеме; написание <code>EXPENCE</code> мок не «исправляет», а вариант <code>EXPENSE</code> отклоняет с подсказкой. Правила сверки <code>totalSum</code> с позициями срез не описывает — это вне области, мок лишь предупреждает в логе.</p><h2 id="callback" tabindex="-1">Callback <a class="header-anchor" href="#callback" aria-label="Permalink to &quot;Callback&quot;">​</a></h2><p>Если в <code>requestMetadata.callbackUrl</code> передан URL (или задан <code>MOCK_FIRST_OFD_CALLBACK_URL</code> — fallback мока <code>[FORK]</code>), после обработки заявки уходит <code>POST</code> с JSON-телом результата плюс <code>externalId</code>/<code>userGroup</code>.</p><p><strong>Публичный срез не закрепляет ни envelope, ни подпись, ни обязательный ACK, ни расписание повторов</strong> — мок не выдумывает HMAC/RSA: подписи нет вовсе. Тело уведомления, условие «любой 2xx = доставлено» и график повторов <code>MOCK_FIRST_OFD_CALLBACK_RETRY_MS</code> × <code>MOCK_FIRST_OFD_CALLBACK_MAX_ATTEMPTS</code> (дефолт 3 × 60 с) — локальная договорённость стенда <code>[FORK]</code>, а не утверждение о протоколе Первого ОФД. Приёмник должен быть идемпотентным, результат подтверждается методом статуса. Расхождение по схеме URL (<code>http://</code> в PDF против <code>https://</code> в примерах) по умолчанию не разрешается в чью-то пользу: принимаются обе схемы, строгий HTTPS включается <code>MOCK_FIRST_OFD_CALLBACK_HTTPS_ONLY=1</code>. Приватный <code>callbackUrl</code> при <code>MOCK_BLOCK_PRIVATE_WEBHOOKS</code> даёт терминальный <code>SSRF_BLOCKED</code> без повторов.</p><h2 id="Идемпотентность-и-externalid" tabindex="-1">Идемпотентность и <code>externalId</code> <a class="header-anchor" href="#Идемпотентность-и-externalid" aria-label="Permalink to &quot;Идемпотентность и `externalId`&quot;">​</a></h2><p><code>externalId</code> — внешний идентификатор вызывающей стороны. Правила дедупликации и срок хранения публично <strong>не подтверждены</strong> <code>[VERIFY]</code>. Мок фиксирует детерминированное поведение: повтор с тем же <code>externalId</code> в той же группе создаёт <strong>новую</strong> заявку со своим <code>requestId</code> (ответ помечается <code>X-Mock-Duplicate-External-Id: 1</code>), обе находятся через <code>statuses</code>. Для сверки сохраняйте выданный <code>requestId</code> — это ключ к статусу и фискальному документу.</p><h2 id="Сценарии-часы-и-диагностика" tabindex="-1">Сценарии, часы и диагностика <a class="header-anchor" href="#Сценарии-часы-и-диагностика" aria-label="Permalink to &quot;Сценарии, часы и диагностика&quot;">​</a></h2><p><code>X-Mock-Scenario</code>/<code>/mock/scenarios</code> поддерживают <code>fail</code> (HTTP 500 на вызове), <code>hang</code>, <code>latency</code>, <code>http-500</code>/<code>http-504</code>, <code>kkt-error</code> и <code>api-error</code> (завершение заявки ошибкой слоя ККТ/API), <code>getToken-error-quirk</code>, <code>webhook-drop</code>/ <code>no-callback</code>, <code>webhook-duplicate</code>/<code>callback-duplicate</code>. Естественные правила стенда возвращают <code>SHIFT_ALREADY_OPEN</code>/<code>SHIFT_NOT_OPEN</code> при повторном открытии/закрытии смены (правила ККТ-слоя срезом не описаны — <code>[FORK]</code>). <code>POST /mock/time</code> принимает <code>{&quot;advance&quot;:&quot;+5s&quot;}</code> (обработка очереди), <code>{&quot;advance&quot;:&quot;+25h&quot;}</code> (истечение токена) и <code>{&quot;advance&quot;:&quot;+60s&quot;}</code> (retry callback). Сценарии, история, токены, журнал и состояние изолируются по <code>X-Mock-Sandbox</code>. Журнал redacts чувствительные поля; в hosted-режиме SSRF-проверка исходящих callback включена по умолчанию.</p><p>В <code>owned</code>-модели (<code>MOCK_HOSTED=1</code>) доступ к своей песочнице даёт owner-token (<code>X-Sandbox-Token</code>). Наблюдаемое ограничение стенда <code>[VERIFY]</code>: если в одном запросе есть и <code>Authorization: Bearer &lt;токен очереди&gt;</code>, и <code>X-Sandbox-Token</code>, ядро (RFC-001) читает owner-token из <code>Authorization</code> и отвечает 401 «знание ID не является доступом» — поведение общее для Bearer-адаптеров, воспроизводится и на <code>vtb-mock</code>. Для локальных сценариев внутри одной песочницы используйте <code>namespaces</code> (self-hosted дефолт) или <code>MOCK_TENANCY=off</code>.</p><h2 id="Переменные-окружения" tabindex="-1">Переменные окружения <a class="header-anchor" href="#Переменные-окружения" aria-label="Permalink to &quot;Переменные окружения&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Переменная</th><th>Default</th><th>Назначение</th></tr></thead><tbody><tr><td><code>MOCK_HOST</code> / <code>MOCK_PORT</code></td><td><code>0.0.0.0</code> / <code>3107</code></td><td>адрес и порт HTTP-сервера</td></tr><tr><td><code>MOCK_FIRST_OFD_LOGIN</code></td><td><code>firstofdmocktest</code></td><td>синтетический <code>login</code> организации</td></tr><tr><td><code>MOCK_FIRST_OFD_PASS</code></td><td><code>11111111-2222-4333-8444-555555555555</code></td><td>синтетический API-ключ UUID (<code>pass</code>)</td></tr><tr><td><code>MOCK_FIRST_OFD_TOKEN_TTL_SECS</code></td><td><code>86400</code></td><td>срок токена в секундах (24 ч); поддерживает длительность (<code>24h</code>); TTL живёт на виртуальных часах</td></tr><tr><td><code>MOCK_FIRST_OFD_TOKEN_SINGLE</code></td><td><code>false</code></td><td><code>true</code> — повторный <code>getToken</code> аннулирует прежние токены (<code>[VERIFY]</code>-режим среза)</td></tr><tr><td><code>MOCK_FIRST_OFD_PROCESS_MS</code></td><td><code>2000</code></td><td>задержка обработки заявки в очереди на виртуальных часах; поддерживает длительность (<code>1h</code>), <code>0</code> разрешён</td></tr><tr><td><code>MOCK_FIRST_OFD_PUBLIC_BASE_URL</code></td><td><code>http://localhost:${MOCK_FIRST_OFD_HOST_PORT:-3107}</code></td><td>внешний base URL стенда (журнал, sandbox URL)</td></tr><tr><td><code>MOCK_FIRST_OFD_CALLBACK_URL</code></td><td>пусто</td><td>fallback callback URL, когда заявка не передала <code>requestMetadata.callbackUrl</code> (<code>[FORK]</code> мока)</td></tr><tr><td><code>MOCK_FIRST_OFD_CALLBACK_RETRY_MS</code></td><td><code>60000</code> (<code>60s</code>)</td><td>интервал retry; число в миллисекундах либо длительность (<code>60s</code>, <code>1m</code>)</td></tr><tr><td><code>MOCK_FIRST_OFD_CALLBACK_MAX_ATTEMPTS</code></td><td><code>3</code></td><td>максимум доставок; значение меньше 1 нормализуется в 1</td></tr><tr><td><code>MOCK_FIRST_OFD_CALLBACK_HTTPS_ONLY</code></td><td><code>false</code></td><td><code>true</code> — отклонять <code>http://</code> в <code>callbackUrl</code> (строгое чтение PDF; расхождение №3 среза)</td></tr><tr><td><code>MOCK_FIRST_OFD_USER_GROUPS</code></td><td><code>MOCKGROUP,firstofd-mock</code></td><td>синтетический каталог <code>requestMetadata.userGroup</code>; <code>*</code> отключает проверку группы</td></tr><tr><td><code>MOCK_STATE_FILE</code></td><td>пусто</td><td>сохранение доменного состояния/очереди между рестартами</td></tr><tr><td><code>MOCK_SANDBOX_FILE</code></td><td><code>&lt;MOCK_STATE_FILE&gt;.sandboxes.json</code></td><td>база RFC-001 реестра песочниц</td></tr><tr><td><code>MOCK_SANDBOX_SWEEP_MS</code></td><td><code>60000</code></td><td>интервал sweep TTL/retention, когда worker включён</td></tr><tr><td><code>MOCK_BLOCK_PRIVATE_WEBHOOKS</code></td><td><code>false</code> (hosted → <code>true</code>)</td><td>запрет исходящих callback в private/reserved адреса; SSRF-отказ терминален</td></tr><tr><td><code>MOCK_VIRTUAL_CLOCK</code></td><td>текущее время</td><td>начальное значение виртуальных часов</td></tr><tr><td><code>MOCK_ADMIN_TOKEN</code> / <code>MOCK_OPERATOR_TOKEN</code></td><td>пусто</td><td>защита управляющих <code>/admin*</code> и <code>/mock/*</code></td></tr><tr><td><code>MOCK_HOSTED</code></td><td><code>false</code></td><td><code>true</code> включает hosted fail-closed для управляющих поверхностей и default SSRF-защиту</td></tr><tr><td><code>MOCK_TENANCY</code></td><td>авто</td><td>sandbox-модель RFC-001 (<code>off</code>, <code>namespaces</code>, <code>owned</code>)</td></tr><tr><td><code>MOCK_SANDBOX_TOKEN</code></td><td>пусто</td><td>owner-token default sandbox в <code>owned</code>-модели; при <code>MOCK_HOSTED=1</code> без него <code>default</code> не обслуживается (MS-12)</td></tr><tr><td><code>MOCK_SANDBOX_TTL_MS</code> / <code>MOCK_SANDBOX_MAX</code></td><td><code>owned: 24h</code> / <code>owned: 100</code></td><td>аренда и число песочниц</td></tr><tr><td><code>MOCK_SANDBOX_MAX_DOCUMENTS</code></td><td><code>owned: 5000</code></td><td>квота заявок + документов + callback-записей на sandbox</td></tr><tr><td><code>MOCK_SANDBOX_RETENTION_MS</code></td><td><code>0</code></td><td>retention терминальных callback-записей; заявки и документы не удаляются</td></tr><tr><td><code>MOCK_SANDBOX_HOST_SUFFIX</code></td><td>пусто</td><td>опциональный hostname-формат sandbox URL</td></tr><tr><td><code>MOCK_SANDBOX_CREATE_LIMIT</code></td><td><code>owned: 20</code></td><td>rate-limit создания sandbox на IP</td></tr></tbody></table><h2 id="Протокольные-файлы-и-тесты" tabindex="-1">Протокольные файлы и тесты <a class="header-anchor" href="#Протокольные-файлы-и-тесты" aria-label="Permalink to &quot;Протокольные файлы и тесты&quot;">​</a></h2><ul><li>Манифест drift-проверки: <a href="https://github.com/rucorp/mock-services/blob/main/protocols/first-ofd-okassa.json" target="_blank" rel="noreferrer"><code>protocols/first-ofd-okassa.json</code></a>.</li><li>OpenAPI: <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/first-ofd-mock.openapi.json" target="_blank" rel="noreferrer"><code>docs/openapi/first-ofd-mock.openapi.json</code></a>, также <code>GET /openapi.json</code>.</li><li>Selftest (getToken/TTL, очередь и оба слоя ошибок, смены, <code>statuses</code>/<code>receipts</code>, callback без подписи, SSRF, RFC-001): <code>npm run test:first-ofd</code>.</li><li>Гайд «за 10 минут»: <a href="./../../docs/integration/first-ofd"><code>docs/integration/first-ofd.md</code></a>.</li><li>Ограничения безопасности общие с проектом: <a href="./../../SECURITY"><code>SECURITY.md</code></a>.</li></ul><h2 id="Байтовые-квоты-состояния-pd-02" tabindex="-1">Байтовые квоты состояния (PD-02) <a class="header-anchor" href="#Байтовые-квоты-состояния-pd-02" aria-label="Permalink to &quot;Байтовые квоты состояния (PD-02)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Env</th><th>Дефолт</th><th>Назначение</th></tr></thead><tbody><tr><td><code>MOCK_SANDBOX_MAX_STATE_BYTES</code></td><td>пусто: <code>8388608</code> (8 МиБ) при <code>maxDocuments &gt; 0</code>, иначе без лимита</td><td>байты JSON одной песочницы; <code>0</code> выключает</td></tr><tr><td><code>MOCK_SANDBOX_GLOBAL_MAX_STATE_BYTES</code></td><td><code>67108864</code> (64 МиБ)</td><td>сумма байт JSON всех песочниц рантайма, включая <code>default</code>; <code>0</code> выключает</td></tr></tbody></table><p>Значения задаются в целых байтах. Пусто сохраняет дефолты. Квота per-sandbox не ограничивает память контейнера; общий бюджет меньше <code>mem_limit: 128m</code>, но не равен RSS. Превышение глобального бюджета на записи или байтовых квот при импорте <code>/mock/state</code> → HTTP 400, <code>errorCode: 400</code>, <code>kind: &#39;bytes&#39;</code>, <code>code: sandbox_state_budget_exceeded</code> / <code>sandbox_state_quota_exceeded</code>, с откатом отклонённого состояния. Правила/история/журнал остаются volatile. Подробности и границы — <a href="./../../packages/core/README#байтовые-квоты-песочниц-pd-02-74">документация ядра</a>.</p>',34)])])}const k=d(a,[["render",s]]);export{h as __pageData,k as default};
